        home_cta_button: 'Crea tu cuenta',
        home_why_title: 'Más que una plataforma',
        home_why_subtitle: 'Cnote Bakery (Console Notebook) es como un hobby dedicado al mundo de las consolas de videojuegos. Reúne historia, tecnología y comunidad en un solo lugar. Pero su objetivo va más allá de la documentación. Cnote Bakery busca revivir una parte de nosotros: el espíritu auténtico del juego que muchos han perdido a medida que la industria ha cambiado. Aquí puedes descubrir consolas, aprender cómo funcionan y ayudar a preservar una parte importante de la cultura del videojuego. Estás a solo un botón de comenzar tu propio viaje en el mundo de las consolas, conectarte con otros entusiastas y sumergirte en el rico mundo de la historia y la tecnología de los videojuegos.',
